def generate(seed):
    r = random.Random(seed)
    while True:
        W = r.randint(28, 36)
        cols = []
        c = 3
        while c < W - 4:
            if r.random() < 0.5:
                cols.append(c); c += r.randint(4, 7)
            else:
                c += 1
        if not 4 <= len(cols) <= 8:
            continue
        p = ["."] * W
        tot = tall = 0
        for c in cols:
            h = r.choice((1, 2, 2, 3, 3)); p[c] = str(h); tot += h
            tall += h > 1
        if tot < 10 or tall < 3:
            continue
        pool = [k for k in range(2, min(9, tot - 2)) if k not in (len(cols), tot)]
        if pool:
            return "".join(p) + "/" + str(r.choice(pool))

