def bgrid(p, D):
    return ["".join("|" if q > "." and int(q) >= D - i else "." for q in p) for i in range(D)]

def far(rw, a):
    return all(abs(a - b) >= 4 for (b, _) in rw)

def nibs(p, D):
    W = len(p); bg = bgrid(p, D); out = []
    for i in range(D):
        b = bg[i]
        for c in range(W):
            if b[c] != "|":
                continue
            if c >= 3 and b[c-3:c] == "...":
                out.append((i, c, c - 3, 0))
            if c + 4 <= W and b[c+1:c+4] == "...":
                out.append((i, c, c + 1, 1))
    return out

def fills(p, D):
    W = len(p); bg = bgrid(p, D); out = []
    for i in range(D):
        b = bg[i]
        for a in range(W - 2):
            if b[a:a+3] != "...":
                continue
            for d in (0, 1):
                no = a + 3 if d == 0 else a - 1
                ta = a - 1 if d == 0 else a + 3
                if 0 <= no < W and b[no] == "|":
                    continue
                out.append((i, a, d, 0 <= ta < W and b[ta] == "|"))
    return out

def render(p, D, rows):
    bg = bgrid(p, D)
    out = ["~" * len(p)]
    for i in range(D):
        row = list(bg[i])
        for (a, d) in rows[i]:
            row[a:a+3] = list("><>" if d == 0 else "<><")
        out.append("".join(row))
    out.append("#" * len(p))
    return "\n".join(out)

def stats(p, D, rows):
    W = len(p); bg = bgrid(p, D)
    F = R = Lf = fn = tl = 0
    spots = set(); touch = set(); per = []
    ps = pnn = ptt = 0
    for i in range(D):
        rs = sorted(rows[i]); per.append(len(rs))
        for (a, d) in rs:
            F += 1
            if d == 0: R += 1
            else: Lf += 1
            no = a + 3 if d == 0 else a - 1
            ba = a - 1 if d == 0 else a + 3
            if 0 <= no < W and bg[i][no] == "|":
                fn += 1; spots.add((i, no)); touch.add(no)
            if 0 <= ba < W and bg[i][ba] == "|":
                tl += 1; touch.add(ba)
        for u, v in zip(rs, rs[1:]):
            if u[1] == v[1]: ps += 1
            elif u[1] == 0: pnn += 1
            else: ptt += 1
    return dict(F=F, R=R, Lf=Lf, fn=fn, tl=tl, tc=fn + tl, fr=F - fn - tl,
                nib=len(spots), pl=sum(1 for q in p if q > "."),
                pc=sum(int(q) for q in p if q > "."), D=D,
                bot=per[-1], top=per[0], mx=max(per), ps=ps, pnn=pnn, ptt=ptt,
                pt=len(touch))

DEC = ("F","R","Lf","tl","tc","fr","pl","pc","D","bot","top","mx","ps","pnn","ptt","pt")

def okay(p, D, rows, N):
    s = stats(p, D, rows)
    if s["fn"] != N or s["nib"] != N: return False
    if s["tl"] < 1 or s["fr"] < 1: return False
    if s["R"] < 2 or s["Lf"] < 2: return False
    bad = {s[k] for k in DEC}
    bad |= {s["F"] - s["D"], s["F"] - s["fn"], s["tc"] - s["fn"]}
    return N not in bad

def solve(clue):
    p, n = clue.split("/")
    N = int(n)
    r = random.Random(clue)
    pre = {}
    for D in (4, 5, 6):
        nb = nibs(p, D)
        pre[D] = (nb, sorted({(i, c) for (i, c, _, _) in nb}), fills(p, D))
    Ds = [D for D in (4, 5, 6) if D != N and len(pre[D][1]) >= N]
    if not Ds: return ""
    for _ in range(3000):
        D = r.choice(Ds)
        nb, cells, fl = pre[D]
        rows = [[] for _ in range(D)]
        ok = True
        for (i, c) in r.sample(cells, N):
            opt = [(a, d) for (j, cc, a, d) in nb if j == i and cc == c and far(rows[i], a)]
            if not opt:
                ok = False; break
            rows[i].append(r.choice(opt))
        if not ok: continue
        k = r.choice((2, 2, 2, 3, 3, 3, 4, 4, 5))
        cand = list(fl); r.shuffle(cand)
        need = [1, 1]
        for (i, a, d, t) in cand:
            if k == 0: break
            if not far(rows[i], a): continue
            if need[t] or k > need[0] + need[1]:
                rows[i].append((a, d)); k -= 1
                if need[t]: need[t] = 0
        if k or need[0] or need[1]: continue
        if okay(p, D, rows, N):
            return render(p, D, rows)
    return ""

